import { useWebSocket } from './hooks/useWebSocket';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { getRenderer } from './renderers/registry';
import type { WorkflowRunState } from './types';
import './App.css';

export function App() {
  const { state, selectRun, connected } = useWebSocket();

  const selectedWorkflow = state.workflows.find(
    (w) => w.id === state.selectedRunId,
  );

  if (!selectedWorkflow) {
    return (
      <div className="app">
        <Header connected={connected} />
        <div className="app-body">
          <Sidebar
            workflows={state.workflows}
            selectedRunId={state.selectedRunId}
            onSelectRun={selectRun}
          />
          <main className="app-main">
            <div className="app-main-placeholder">
              Select a workflow from the sidebar
            </div>
          </main>
        </div>
      </div>
    );
  }

  const Renderer = getRenderer(selectedWorkflow.workflowName);

  const runState: WorkflowRunState | undefined =
    state.runStates.get(selectedWorkflow.id) ?? {
      summary: selectedWorkflow,
      agents: new Map(),
      currentPhase: '',
      completedPhases: [],
    };

  return (
    <div className="app">
      <Header connected={connected} />
      <div className="app-body">
        <Sidebar
          workflows={state.workflows}
          selectedRunId={state.selectedRunId}
          onSelectRun={selectRun}
        />
        <main className="app-main">
          {Renderer && runState ? (
            <Renderer runState={runState} />
          ) : (
            <div className="app-main-placeholder">
              Workflow selected, but no renderer available
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.app-body {
  display: flex;
  flex: 1;
  overflow: hidden;
}

.app-main {
  flex: 1;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: var(--engin-bg-primary);
}

.app-main-placeholder {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--engin-text-muted);
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './index.css';
import { App } from './App';
import './renderers/develop/DevelopRenderer'; // triggers registration side effect

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

/**
 * Frontend types for the engin web interface.
 *
 * Mirrors the backend protocol types from src/web/types.ts (T02) but
 * does NOT import from the backend.  The additional frontend-specific
 * types (WorkflowRunState, AppGlobalState) manage UI state client-side.
 */

// ─── Shared value types (mirrored from T02) ─────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages (mirrored from T02) ───────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages (mirrored from T02) ───────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Frontend-specific state types ──────────────────────────────────────────

export interface WorkflowRunState {
  summary: WorkflowSummary;
  agents: Map<string, AgentWindowState>;
  currentPhase: string;
  completedPhases: string[];
}

export interface AppGlobalState {
  workflows: WorkflowSummary[];
  selectedRunId: string | null;
  runStates: Map<string, WorkflowRunState>;
}

// ─── Type guard ─────────────────────────────────────────────────────────────

export function isServerMessage(data: unknown): data is ServerMessage {
  return typeof data === 'object' && data !== null && 'type' in data;
}

import type { ComponentType } from 'react';
import type { WorkflowRendererProps } from './types';

const registry = new Map<string, ComponentType<WorkflowRendererProps>>();

export function registerRenderer(
  name: string,
  comp: ComponentType<WorkflowRendererProps>,
): void {
  registry.set(name, comp);
}

export function getRenderer(
  name: string,
): ComponentType<WorkflowRendererProps> | undefined {
  return registry.get(name);
}

import type { WorkflowRunState } from '../types';

export interface WorkflowRendererProps {
  runState: WorkflowRunState;
}

/**
 * DevelopRenderer — top-level renderer for "develop" workflows.
 *
 * Composes the horizontal ProgressIndicator (phase bar) with an AgentGrid
 * showing per-agent log panels.  A small label in .develop-content shows
 * the current (active) phase name.
 */

import type { WorkflowRendererProps } from '../types';
import { registerRenderer } from '../registry';
import { buildDevelopState } from './types';
import { ProgressIndicator } from './ProgressIndicator';
import { AgentGrid } from './AgentGrid';
import './DevelopRenderer.css';

export function DevelopRenderer({ runState }: WorkflowRendererProps) {
  const state = buildDevelopState(runState);

  return (
    <div className="develop-renderer">
      <ProgressIndicator phases={state.phases} />
      <div className="develop-content">
        {state.currentPhase && (
          <div className="develop-phase-label">{state.currentPhase}</div>
        )}
        <AgentGrid agents={state.agents} />
      </div>
    </div>
  );
}

registerRenderer('develop', DevelopRenderer);

import { useEffect, useRef, useState, useCallback } from 'react';
import type { AppGlobalState, ClientMessage, ServerMessage } from '../types';
import { isServerMessage } from '../types';

export function useWebSocket() {
  const [state, setState] = useState<AppGlobalState>({
    workflows: [],
    selectedRunId: null,
    runStates: new Map(),
  });

  const [connected, setConnected] = useState(false);

  const wsRef = useRef<WebSocket | null>(null);
  const stateRef = useRef(state);
  stateRef.current = state;

  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const connect = useCallback(() => {
    // Determine WS URL
    const wsEndpoint =
      (typeof window !== 'undefined' && (window as any).__WS_ENDPOINT__) ||
      'ws://localhost:3619/ws';

    const ws = new WebSocket(wsEndpoint);
    wsRef.current = ws;

    ws.onopen = () => {
      console.log('WebSocket connected');
      setConnected(true);
    };

    ws.onmessage = (event: MessageEvent) => {
      try {
        const data: unknown = JSON.parse(event.data as string);
        if (!isServerMessage(data)) {
          console.warn('Received invalid message from server', data);
          return;
        }
        handleServerMessage(data);
      } catch (err) {
        console.error('Failed to parse WebSocket message', err);
      }
    };

    ws.onerror = (error: Event) => {
      console.error('WebSocket error', error);
    };

    ws.onclose = () => {
      setConnected(false);
      console.log('WebSocket disconnected, reconnecting in 3s...');
      reconnectTimeoutRef.current = setTimeout(() => {
        connect();
      }, 3000);
    };
  }, []);

  function handleServerMessage(msg: ServerMessage) {
    switch (msg.type) {
      case 'init': {
        setState((prev) => ({
          ...prev,
          workflows: msg.workflows,
        }));
        break;
      }
      case 'workflow_started': {
        setState((prev) => ({
          ...prev,
          workflows: [...prev.workflows, msg.summary],
          runStates: new Map(prev.runStates).set(msg.summary.id, {
            summary: msg.summary,
            agents: new Map(),
            currentPhase: '',
            completedPhases: [],
          }),
        }));
        break;
      }
      case 'workflow_sidebar': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.workflowId ? { ...w, sidebar: msg.sidebar } : w
          ),
        }));
        break;
      }
      case 'workflow_phase': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const existing = runStates.get(msg.workflowId);
          if (existing) {
            runStates.set(msg.workflowId, {
              ...existing,
              currentPhase: msg.phase,
              completedPhases: msg.completed,
            });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'workflow_complete': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.summary.id
              ? { ...w, status: msg.summary.status, completedAt: msg.summary.completedAt }
              : w
          ),
        }));
        break;
      }
      case 'workflow_failed': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.summary.id
              ? { ...w, status: msg.summary.status, completedAt: msg.summary.completedAt }
              : w
          ),
        }));
        break;
      }
      case 'agent_spawned': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const existing = runStates.get(msg.workflowId);
          if (existing) {
            const agents = new Map(existing.agents);
            agents.set(msg.agent.agentId, msg.agent);
            runStates.set(msg.workflowId, { ...existing, agents });
          } else {
            // Create new run state if not exists
            const workflow = prev.workflows.find((w) => w.id === msg.workflowId);
            runStates.set(msg.workflowId, {
              summary: workflow!,
              agents: new Map([[msg.agent.agentId, msg.agent]]),
              currentPhase: '',
              completedPhases: [],
            });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'agent_log': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const runState = runStates.get(msg.workflowId);
          if (runState) {
            const agents = new Map(runState.agents);
            const agent = agents.get(msg.agentId);
            if (agent) {
              agents.set(msg.agentId, {
                ...agent,
                log: [...agent.log, msg.entry],
              });
            }
            runStates.set(msg.workflowId, { ...runState, agents });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'agent_complete': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const runState = runStates.get(msg.workflowId);
          if (runState) {
            const agents = new Map(runState.agents);
            const agent = agents.get(msg.agentId);
            if (agent) {
              agents.set(msg.agentId, { ...agent, active: false });
            }
            runStates.set(msg.workflowId, { ...runState, agents });
          }
          return { ...prev, runStates };
        });
        break;
      }
      default:
        // Exhaustiveness check for compile-time safety
        const _exhaustive: never = msg;
        console.warn('Unhandled server message type', _exhaustive);
    }
  }

  const send = useCallback((msg: ClientMessage) => {
    wsRef.current?.send(JSON.stringify(msg));
  }, []);

  const selectRun = useCallback(
    (runId: string) => {
      setState((prev) => ({ ...prev, selectedRunId: runId }));
      send({ type: 'select_workflow', workflowId: runId });
    },
    [send]
  );

  useEffect(() => {
    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      wsRef.current?.close();
      wsRef.current = null;
    };
  }, [connect]);

  return { state, send, selectRun, connected };
}

import './Header.css';

interface HeaderProps {
  connected: boolean;
}

export function Header({ connected }: HeaderProps) {
  return (
    <header className="header">
      <span className="logo">engin</span>
      <span
        className="connection-dot"
        style={{ backgroundColor: connected ? 'var(--engin-success)' : 'var(--engin-error)' }}
      />
    </header>
  );
}

import './Sidebar.css';

import type { WorkflowSummary } from '../types';

interface SidebarProps {
  workflows: WorkflowSummary[];
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
}

/**
 * Returns a human-readable relative time string.
 *
 * - < 60s: "just now"
 * - < 60m: "Xm ago"
 * - < 24h: "Xh ago"
 * - else:  "Xd ago"
 */
function relativeTime(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  const diffSec = Math.floor((now - then) / 1000);

  if (diffSec < 60) return 'just now';
  if (diffSec < 3600) return `${Math.floor(diffSec / 60)}m ago`;
  if (diffSec < 86400) return `${Math.floor(diffSec / 3600)}h ago`;
  return `${Math.floor(diffSec / 86400)}d ago`;
}

const ACTIVE_LABEL = 'Active';
const PAST_LABEL = 'Past';

export function Sidebar({ workflows, selectedRunId, onSelectRun }: SidebarProps) {
  const active = workflows.filter((w) => w.status === 'running');
  const past = workflows.filter((w) => w.status !== 'running');

  const renderItem = (workflow: WorkflowSummary) => {
    const isSelected = workflow.id === selectedRunId;
    const statusClass =
      workflow.status === 'running'
        ? 'running'
        : workflow.status === 'completed'
          ? 'completed'
          : 'failed';

    return (
      <div
        key={workflow.id}
        className={`sidebar-item${isSelected ? ' selected' : ''} ${statusClass}`}
        onClick={() => onSelectRun(workflow.id)}
      >
        <span className={`sidebar-indicator${workflow.status === 'running' ? ' pulsing' : ''}`}>
          {workflow.sidebar.indicator}
        </span>
        <span className="sidebar-title">{workflow.sidebar.title}</span>
        <span className="sidebar-time">{relativeTime(workflow.startedAt)}</span>
      </div>
    );
  };

  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <span className="sidebar-header-text">Workflows</span>
      </div>

      {active.length > 0 && (
        <div className="sidebar-section">
          <span className="sidebar-section-title">{ACTIVE_LABEL}</span>
          {active.map(renderItem)}
        </div>
      )}

      {past.length > 0 && (
        <div className="sidebar-section">
          <span className="sidebar-section-title">{PAST_LABEL}</span>
          {past.map(renderItem)}
        </div>
      )}
    </aside>
  );
}

/**
 * Tests for the root App component.
 *
 * Verifies:
 * - Layout: div.app > Header + div.app-body > Sidebar + main.app-main
 * - No selection state shows placeholder "Select a workflow from the sidebar"
 * - Selected workflow with renderer renders the renderer component
 * - Selected workflow without renderer shows "Workflow selected, but no renderer available"
 * - Header receives connected prop from useWebSocket
 * - Sidebar receives workflows, selectedRunId, and onSelectRun
 * - Fallback runState is created from summary when not in runStates
 */

import '@testing-library/jest-dom/vitest';

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';

import type { ComponentType } from 'react';
import type { AppGlobalState, WorkflowRunState } from '../types';
import type { WorkflowRendererProps } from '../renderers/types';

// ─── Mocks ──────────────────────────────────────────────────────────────────

const mockUseWebSocket = vi.fn();
vi.mock('../hooks/useWebSocket', () => ({
  useWebSocket: () => mockUseWebSocket(),
}));

// We need a proper mock for the registry that we can control per test.
// getRenderer is imported indirectly by App.tsx; we mock the module.
const mockGetRenderer = vi.fn();
vi.mock('../renderers/registry', () => ({
  getRenderer: (...args: Parameters<typeof mockGetRenderer>) => mockGetRenderer(...args),
}));

// ─── Helpers ────────────────────────────────────────────────────────────────

function makeSummary(overrides: Partial<AppGlobalState['workflows'][number]> = {}) {
  return {
    id: 'test-run-1',
    workflowName: 'develop',
    status: 'running' as const,
    sidebar: { title: 'Test Workflow', indicator: '🚀' },
    startedAt: new Date().toISOString(),
    ...overrides,
  };
}

function makeRunState(overrides: Partial<WorkflowRunState> = {}): WorkflowRunState {
  const summary = overrides.summary ?? makeSummary();
  return {
    summary,
    agents: new Map(),
    currentPhase: '',
    completedPhases: [],
    ...overrides,
  };
}

/** A dummy renderer component we can detect in the DOM */
const DummyRenderer: ComponentType<WorkflowRendererProps> = ({ runState }) => (
  <div data-testid="dummy-renderer">
    {runState.summary.sidebar.title} — {runState.currentPhase || 'no phase'}
  </div>
);

// ─── Default mock state ─────────────────────────────────────────────────────

beforeEach(() => {
  vi.clearAllMocks();

  // Default: no workflows, not connected
  mockUseWebSocket.mockReturnValue({
    state: {
      workflows: [],
      selectedRunId: null,
      runStates: new Map(),
    },
    send: vi.fn(),
    selectRun: vi.fn(),
    connected: false,
  });

  // Default: no renderer registered
  mockGetRenderer.mockReturnValue(undefined);
});

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('App', () => {
  it('renders the top-level .app container', async () => {
    const { container } = await renderApp();
    const app = container.querySelector('.app');
    expect(app).toBeInTheDocument();
  });

  it('renders Header inside .app', async () => {
    const { container } = await renderApp();
    const app = container.querySelector('.app');
    expect(app?.querySelector('header.header')).toBeInTheDocument();
  });

  it('renders .app-body div inside .app', async () => {
    const { container } = await renderApp();
    const app = container.querySelector('.app');
    expect(app?.querySelector('.app-body')).toBeInTheDocument();
  });

  it('renders Sidebar inside .app-body', async () => {
    const { container } = await renderApp();
    const appBody = container.querySelector('.app-body');
    expect(appBody?.querySelector('aside.sidebar')).toBeInTheDocument();
  });

  it('renders main.app-main inside .app-body', async () => {
    const { container } = await renderApp();
    const appBody = container.querySelector('.app-body');
    expect(appBody?.querySelector('main.app-main')).toBeInTheDocument();
  });

  // ── Connected prop ──────────────────────────────────────────────────

  it('passes connected=true to Header', async () => {
    mockUseWebSocket.mockReturnValue({
      state: { workflows: [], selectedRunId: null, runStates: new Map() },
      send: vi.fn(),
      selectRun: vi.fn(),
      connected: true,
    });
    const { container } = await renderApp();
    const dot = container.querySelector('.connection-dot') as HTMLElement;
    expect(dot).toHaveStyle({ backgroundColor: 'var(--engin-success)' });
  });

  it('passes connected=false to Header', async () => {
    mockUseWebSocket.mockReturnValue({
      state: { workflows: [], selectedRunId: null, runStates: new Map() },
      send: vi.fn(),
      selectRun: vi.fn(),
      connected: false,
    });
    const { container } = await renderApp();
    const dot = container.querySelector('.connection-dot') as HTMLElement;
    expect(dot).toHaveStyle({ backgroundColor: 'var(--engin-error)' });
  });

  // ── Sidebar props ───────────────────────────────────────────────────

  it('passes workflows to Sidebar', async () => {
    const workflows = [makeSummary({ id: 'w1' }), makeSummary({ id: 'w2' })];
    mockUseWebSocket.mockReturnValue({
      state: {
        workflows,
        selectedRunId: null,
        runStates: new Map(),
      },
      send: vi.fn(),
      selectRun: vi.fn(),
      connected: false,
    });
    const { container } = await renderApp();
    const items = container.querySelectorAll('.sidebar-item');
    expect(items).toHaveLength(2);
  });

  it('passes selectedRunId to Sidebar and highlights selected item', async () => {
    const workflows = [
      makeSummary({ id: 'w1', status: 'running' }),
      makeSummary({ id: 'w2', status: 'completed' }),
    ];
    mockUseWebSocket.mockReturnValue({
      state: {
        workflows,
        selectedRunId: 'w1',
        runStates: new Map(),
      },
      send: vi.fn(),
      selectRun: vi.fn(),
      connected: false,
    });
    const { container } = await renderApp();
    const items = container.querySelectorAll('.sidebar-item');
    expect(items[0]).toHaveClass('selected');
    expect(items[1]).not.toHaveClass('selected');
  });

  it('passes onSelectRun to Sidebar (calls selectRun when item clicked)', async () => {
    const selectRun = vi.fn();
    const workflows = [makeSummary({ id: 'w1' })];
    mockUseWebSocket.mockReturnValue({
      state: {
        workflows,
        selectedRunId: null,
        runStates: new Map(),
      },
      send: vi.fn(),
      selectRun,
      connected: false,
    });
    await renderApp();
    const item = screen.getByText('🚀').closest('.sidebar-item')!;
    fireEvent.click(item);
    expect(selectRun).toHaveBeenCalledWith('w1');
  });

  // ── No selection ────────────────────────────────────────────────────

  it('shows placeholder "Select a workflow from the sidebar" when no workflow selected', async () => {
    mockUseWebSocket.mockReturnValue({
      state: {
        workflows: [],
        selectedRunId: null,
        runStates: new Map(),
      },
      send: vi.fn(),
      selectRun: vi.fn(),
      connected: false,
    });
    await renderApp();
    expect(
      screen.getByText('Select a workflow from the sidebar'),
    ).toBeInTheDocument();
  });

